library(readr)
library(dplyr)
library(parsnip)
library(broom)

# Load Louisiana wide dataset
data_path &lt;- if (file.exists("data/clean/louisiana_wide_clean.csv")) {
  "data/clean/louisiana_wide_clean.csv"
} else {
  "../data/clean/louisiana_wide_clean.csv"
}

la_wide &lt;- read_csv(data_path, show_col_types = FALSE) |&gt;
  mutate(period = factor(period, levels = c("pre_ban", "post_ban")))

# Fit linear regression model
linear_reg() |&gt;
  set_engine("lm") |&gt;
  fit(g3_12_math ~ period, data = la_wide) |&gt;
  tidy(conf.int = TRUE) |&gt;
  select(term, estimate, conf.low, conf.high)

# A tibble: 2 × 4
  term           estimate conf.low conf.high
  &lt;chr&gt;             &lt;dbl&gt;    &lt;dbl&gt;     &lt;dbl&gt;
1 (Intercept)       29.0     28.0      30.1 
2 periodpost_ban     1.38    -1.44      4.20
